1	//! Rust port of `tests/test6.cpp`.
2	//!
3	//! Builds two sorted sets -- `0..n` and the even numbers `0, 2, ..., 2n-2` --
4	//! unions them, then reports the three sizes followed by a membership check for
5	//! every value in `0..n`.
6	//!
7	//! The single optional argument is the count `n`, defaulting to 6, and is
8	//! parsed with C `atoi` semantics so that non-numeric input becomes 0 exactly
9	//! as it did in the original.
10	
11	#[path = "src/lib.rs"]
12	mod sortedcontainers;
13	
14	use std::io::{self, BufWriter, Write};
15	
16	use sortedcontainers::{c_atoi, SortedSet};
17	
18	fn main() {
19	    let argv: Vec<String> = std::env::args_os()
20	        .map(|arg| arg.to_string_lossy().into_owned())
21	        .collect();
22	
23	    let mut n: i32 = 6;
24	    if argv.len() > 1 {
25	        n = c_atoi(&argv[1]);
26	    }
27	
28	    let mut s1: SortedSet<i32> = SortedSet::new();
29	    let mut s2: SortedSet<i32> = SortedSet::new();
30	    let mut i: i32 = 0;
31	    while i < n {
32	        s1.insert(i);
33	        // Wrapping mirrors what the C++ `int` arithmetic does on overflow.
34	        s2.insert(i.wrapping_mul(2));
35	        i = i.wrapping_add(1);
36	    }
37	
38	    let s3 = s1.union_with(&s2);
39	
40	    // `std::cout` is line-buffered by `endl`; one buffered writer, flushed at
41	    // the end, produces the same bytes.
42	    let stdout = io::stdout();
43	    let mut out = BufWriter::new(stdout.lock());
44	
45	    writeln!(out, "{}", s1.len()).expect("write to stdout");
46	    writeln!(out, "{}", s2.len()).expect("write to stdout");
47	    writeln!(out, "{}", s3.len()).expect("write to stdout");
48	
49	    let mut i: i32 = 0;
50	    while i < n {
51	        // `std::cout` prints a bool as 1 or 0 without `boolalpha`.
52	        write!(out, "{} ", u8::from(s3.contains(&i))).expect("write to stdout");
53	        i = i.wrapping_add(1);
54	    }
55	    writeln!(out).expect("write to stdout");
56	
57	    out.flush().expect("flush stdout");
58	}
