1	//! Faithful Rust versions of the C `<stdlib.h>` string-to-integer routines.
2	//!
3	//! The original program parsed its argument with `std::atoi`, which never
4	//! reports failure: it skips leading whitespace, accepts one optional sign,
5	//! consumes as many digits as it can, and yields `0` when there are none.
6	//! `Rust`'s `str::parse` rejects all of those inputs instead, so the C
7	//! behaviour is reproduced here rather than approximated.
8	
9	/// Matches the C `isspace` classification for the default locale.
10	fn is_c_space(byte: u8) -> bool {
11	    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
12	}
13	
14	/// Equivalent of `strtol(s, NULL, 10)`.
15	///
16	/// Values that do not fit saturate at [`i64::MIN`] / [`i64::MAX`], exactly as
17	/// `strtol` clamps to `LONG_MIN` / `LONG_MAX` when it sets `ERANGE`.
18	pub fn c_strtol(s: &str) -> i64 {
19	    let bytes = s.as_bytes();
20	    let mut at = 0usize;
21	
22	    while at < bytes.len() && is_c_space(bytes[at]) {
23	        at += 1;
24	    }
25	
26	    let mut negative = false;
27	    if at < bytes.len() && (bytes[at] == b'+' || bytes[at] == b'-') {
28	        negative = bytes[at] == b'-';
29	        at += 1;
30	    }
31	
32	    let mut magnitude: i64 = 0;
33	    let mut saturated = false;
34	    while at < bytes.len() && bytes[at].is_ascii_digit() {
35	        let digit = i64::from(bytes[at] - b'0');
36	        if !saturated {
37	            match magnitude.checked_mul(10).and_then(|v| v.checked_add(digit)) {
38	                Some(next) => magnitude = next,
39	                // Keep scanning digits, as `strtol` does, but stop accumulating.
40	                None => saturated = true,
41	            }
42	        }
43	        at += 1;
44	    }
45	
46	    if saturated {
47	        // `-9223372036854775808` overflows the positive magnitude yet is a
48	        // representable result; `i64::MIN` is both the clamp and the answer.
49	        return if negative { i64::MIN } else { i64::MAX };
50	    }
51	    if negative {
52	        -magnitude
53	    } else {
54	        magnitude
55	    }
56	}
57	
58	/// Equivalent of `atoi(s)`: `strtol` truncated to `int` width.
59	///
60	/// glibc implements `atoi` as `(int) strtol(...)`, so out-of-range input wraps
61	/// modulo 2^32 rather than clamping. `atoi("2147483648")` is `-2147483648`.
62	pub fn c_atoi(s: &str) -> i32 {
63	    c_strtol(s) as i32
64	}
65	
66	#[cfg(test)]
67	mod tests {
68	    use super::*;
69	
70	    #[test]
71	    fn plain_decimal_numbers() {
72	        assert_eq!(c_atoi("0"), 0);
73	        assert_eq!(c_atoi("6"), 6);
74	        assert_eq!(c_atoi("42"), 42);
75	        assert_eq!(c_atoi("000123"), 123);
76	        assert_eq!(c_atoi("-7"), -7);
77	        assert_eq!(c_atoi("+5"), 5);
78	        assert_eq!(c_atoi("-0"), 0);
79	    }
80	
81	    #[test]
82	    fn leading_whitespace_is_skipped() {
83	        assert_eq!(c_atoi("   7"), 7);
84	        assert_eq!(c_atoi("\t\n\r\x0b\x0c8"), 8);
85	        assert_eq!(c_atoi("  7  "), 7);
86	        assert_eq!(c_atoi("  -7"), -7);
87	        // Whitespace after the sign terminates the number.
88	        assert_eq!(c_atoi("- 7"), 0);
89	        assert_eq!(c_atoi("+ 7"), 0);
90	    }
91	
92	    #[test]
93	    fn parsing_stops_at_the_first_non_digit() {
94	        assert_eq!(c_atoi("12abc"), 12);
95	        assert_eq!(c_atoi("3.9"), 3);
96	        assert_eq!(c_atoi("1e3"), 1);
97	        assert_eq!(c_atoi("0x10"), 0);
98	        assert_eq!(c_atoi("010"), 10);
99	        assert_eq!(c_atoi("5-3"), 5);
100	        assert_eq!(c_atoi("2 99"), 2);
101	    }
102	
103	    #[test]
104	    fn absent_digits_yield_zero() {
105	        assert_eq!(c_atoi(""), 0);
106	        assert_eq!(c_atoi("abc"), 0);
107	        assert_eq!(c_atoi("   "), 0);
108	        assert_eq!(c_atoi("-"), 0);
109	        assert_eq!(c_atoi("+"), 0);
110	        assert_eq!(c_atoi("--5"), 0);
111	        assert_eq!(c_atoi("+-5"), 0);
112	        assert_eq!(c_atoi("\u{fffd}5"), 0);
113	    }
114	
115	    #[test]
116	    fn out_of_range_input_wraps_like_a_c_int_cast() {
117	        assert_eq!(c_atoi("2147483647"), i32::MAX);
118	        assert_eq!(c_atoi("-2147483648"), i32::MIN);
119	        assert_eq!(c_atoi("2147483648"), i32::MIN);
120	        assert_eq!(c_atoi("4294967296"), 0);
121	        assert_eq!(c_atoi("-2147483649"), i32::MAX);
122	        // Beyond `long`: `strtol` clamps, then the cast truncates.
123	        assert_eq!(c_strtol("9223372036854775807"), i64::MAX);
124	        assert_eq!(c_strtol("9223372036854775808"), i64::MAX);
125	        assert_eq!(c_strtol("99999999999999999999999"), i64::MAX);
126	        assert_eq!(c_strtol("-9223372036854775808"), i64::MIN);
127	        assert_eq!(c_strtol("-9223372036854775809"), i64::MIN);
128	        assert_eq!(c_strtol("-99999999999999999999999"), i64::MIN);
129	        assert_eq!(c_atoi("9223372036854775807"), -1);
130	        assert_eq!(c_atoi("99999999999999999999999"), -1);
131	        assert_eq!(c_atoi("-9223372036854775808"), 0);
132	        assert_eq!(c_atoi("-99999999999999999999999"), 0);
133	        // 0x174876E7FF truncated to 32 bits.
134	        assert_eq!(c_atoi("99999999999"), 1215752191);
135	    }
136	}
