1	//! A sorted list backed by a two-level list-of-lists layout.
2	//!
3	//! Values live in a `Vec` of sorted sublists, each holding at most `2 * load`
4	//! elements. Because every sublist is small, inserting or removing a value only
5	//! shifts a bounded number of elements instead of the whole sequence.
6	//!
7	//! A positional index tree (a flattened, implicit binary tree of subtree sizes)
8	//! sits on top of the sublists so that lookup by rank -- `get`, `pop`,
9	//! `index_of` -- stays logarithmic rather than scanning every sublist.
10	
11	use std::cmp::Ordering;
12	use std::fmt;
13	use std::ops::Index;
14	
15	/// Default maximum sublist occupancy before a sublist is split in half.
16	pub const DEFAULT_LOAD_FACTOR: usize = 1000;
17	
18	/// A sorted sequence that keeps duplicates.
19	pub struct SortedList<T> {
20	    /// Sorted sublists; concatenating them yields the whole sorted sequence.
21	    /// A sublist is never empty.
22	    lists: Vec<Vec<T>>,
23	    /// Flattened index tree of subtree sizes, or empty when not built.
24	    index: Vec<usize>,
25	    /// Offset of the leaf row (the per-sublist lengths) inside `index`.
26	    offset: usize,
27	    /// Total number of elements.
28	    len: usize,
29	    /// Target sublist occupancy.
30	    load: usize,
31	}
32	
33	impl<T> SortedList<T> {
34	    /// Creates an empty list using [`DEFAULT_LOAD_FACTOR`].
35	    pub fn new() -> Self {
36	        Self::with_load_factor(DEFAULT_LOAD_FACTOR)
37	    }
38	
39	    /// Creates an empty list whose sublists hold up to `2 * load` elements.
40	    ///
41	    /// # Panics
42	    ///
43	    /// Panics if `load` is zero.
44	    pub fn with_load_factor(load: usize) -> Self {
45	        assert!(load > 0, "load factor must be positive");
46	        SortedList {
47	            lists: Vec::new(),
48	            index: Vec::new(),
49	            offset: 0,
50	            len: 0,
51	            load,
52	        }
53	    }
54	
55	    /// Number of elements in the list.
56	    pub fn len(&self) -> usize {
57	        self.len
58	    }
59	
60	    /// Returns `true` when the list holds no elements.
61	    pub fn is_empty(&self) -> bool {
62	        self.len == 0
63	    }
64	
65	    /// The configured load factor.
66	    pub fn load_factor(&self) -> usize {
67	        self.load
68	    }
69	
70	    /// Removes every element, keeping the load factor.
71	    pub fn clear(&mut self) {
72	        self.lists.clear();
73	        self.index.clear();
74	        self.offset = 0;
75	        self.len = 0;
76	    }
77	
78	    /// Iterates over the elements in ascending order.
79	    pub fn iter(&self) -> Iter<'_, T> {
80	        Iter {
81	            inner: self.lists.iter().flatten(),
82	            remaining: self.len,
83	        }
84	    }
85	
86	    /// Returns the element at rank `idx`, or `None` when out of bounds.
87	    pub fn get(&self, idx: usize) -> Option<&T> {
88	        let (pos, sub_idx) = self.locate_rank(idx)?;
89	        Some(&self.lists[pos][sub_idx])
90	    }
91	
92	    /// Returns the smallest element.
93	    pub fn first(&self) -> Option<&T> {
94	        self.lists.first().and_then(|sub| sub.first())
95	    }
96	
97	    /// Returns the largest element.
98	    pub fn last(&self) -> Option<&T> {
99	        self.lists.last().and_then(|sub| sub.last())
100	    }
101	
102	    /// Removes and returns the element at rank `idx`.
103	    pub fn pop(&mut self, idx: usize) -> Option<T> {
104	        let (pos, sub_idx) = self.locate_rank(idx)?;
105	        Some(self.delete_at(pos, sub_idx))
106	    }
107	
108	    /// Removes and returns the smallest element.
109	    pub fn pop_first(&mut self) -> Option<T> {
110	        if self.len == 0 {
111	            None
112	        } else {
113	            Some(self.delete_at(0, 0))
114	        }
115	    }
116	
117	    /// Removes and returns the largest element.
118	    pub fn pop_last(&mut self) -> Option<T> {
119	        if self.len == 0 {
120	            return None;
121	        }
122	        let pos = self.lists.len() - 1;
123	        let sub_idx = self.lists[pos].len() - 1;
124	        Some(self.delete_at(pos, sub_idx))
125	    }
126	
127	    /// Copies the elements into a `Vec` in ascending order.
128	    pub fn to_vec(&self) -> Vec<T>
129	    where
130	        T: Clone,
131	    {
132	        self.iter().cloned().collect()
133	    }
134	
135	    /// Consumes the list, returning its elements in ascending order.
136	    pub fn into_vec(self) -> Vec<T> {
137	        let mut out = Vec::with_capacity(self.len);
138	        for sub in self.lists {
139	            out.extend(sub);
140	        }
141	        out
142	    }
143	
144	    /// Rebuilds the positional index tree over the current sublists.
145	    ///
146	    /// The tree is stored as consecutive rows, deepest row last: the final row
147	    /// holds one entry per sublist and each row above holds the pairwise sums of
148	    /// the row below it.
149	    fn build_index(&mut self) {
150	        self.index.clear();
151	        self.offset = 0;
152	        if self.lists.is_empty() {
153	            return;
154	        }
155	
156	        let row0: Vec<usize> = self.lists.iter().map(Vec::len).collect();
157	        if row0.len() == 1 {
158	            self.index = row0;
159	            return;
160	        }
161	
162	        let mut row1: Vec<usize> = row0.chunks(2).map(|pair| pair.iter().sum()).collect();
163	        if row1.len() == 1 {
164	            self.index = row1;
165	            self.index.extend_from_slice(&row0);
166	            self.offset = 1;
167	            return;
168	        }
169	
170	        // Pad the second row to a power of two so every row above it is even
171	        // sized and the tree stays perfectly shaped.
172	        let size = row1.len().next_power_of_two();
173	        row1.resize(size, 0);
174	
175	        let mut rows: Vec<Vec<usize>> = vec![row0, row1];
176	        while rows.last().map_or(0, Vec::len) > 1 {
177	            let row: Vec<usize> = rows
178	                .last()
179	                .unwrap()
180	                .chunks(2)
181	                .map(|pair| pair.iter().sum())
182	                .collect();
183	            rows.push(row);
184	        }
185	
186	        let total: usize = rows.iter().map(Vec::len).sum();
187	        let mut index = Vec::with_capacity(total);
188	        for row in rows.into_iter().rev() {
189	            index.extend(row);
190	        }
191	        self.index = index;
192	        self.offset = size * 2 - 1;
193	    }
194	
195	    /// Ensures the index tree is present whenever there is anything to index.
196	    fn ensure_index(&mut self) {
197	        if self.index.is_empty() && !self.lists.is_empty() {
198	            self.build_index();
199	        }
200	    }
201	
202	    /// Translates a global rank into `(sublist, offset within sublist)`.
203	    fn locate_rank(&self, rank: usize) -> Option<(usize, usize)> {
204	        if rank >= self.len {
205	            return None;
206	        }
207	        let mut idx = rank;
208	        if idx < self.lists[0].len() {
209	            return Some((0, idx));
210	        }
211	        if self.index.is_empty() {
212	            // No index available: walk the sublists directly.
213	            let mut pos = 0;
214	            while idx >= self.lists[pos].len() {
215	                idx -= self.lists[pos].len();
216	                pos += 1;
217	            }
218	            return Some((pos, idx));
219	        }
220	
221	        let mut pos = 0usize;
222	        let mut child = 1usize;
223	        while child < self.index.len() {
224	            let size = self.index[child];
225	            if idx < size {
226	                pos = child;
227	            } else {
228	                idx -= size;
229	                pos = child + 1;
230	            }
231	            child = (pos << 1) + 1;
232	        }
233	        Some((pos - self.offset, idx))
234	    }
235	
236	    /// Translates `(sublist, offset within sublist)` into a global rank.
237	    fn rank_of(&self, pos: usize, sub_idx: usize) -> usize {
238	        if pos == 0 {
239	            return sub_idx;
240	        }
241	        if self.index.is_empty() {
242	            let before: usize = self.lists[..pos].iter().map(Vec::len).sum();
243	            return before + sub_idx;
244	        }
245	        // Sum the left siblings encountered while walking up to the root.
246	        let mut total = 0usize;
247	        let mut node = pos + self.offset;
248	        while node > 0 {
249	            if node & 1 == 0 {
250	                total += self.index[node - 1];
251	            }
252	            node = (node - 1) >> 1;
253	        }
254	        total + sub_idx
255	    }
256	
257	    /// Records one extra element in `lists[pos]`, splitting it when overfull.
258	    fn expand(&mut self, pos: usize) {
259	        if self.lists[pos].len() > (self.load << 1) {
260	            let half = self.lists[pos].split_off(self.load);
261	            self.lists.insert(pos + 1, half);
262	            self.index.clear();
263	            self.offset = 0;
264	        } else if !self.index.is_empty() {
265	            let mut node = self.offset + pos;
266	            while node > 0 {
267	                self.index[node] += 1;
268	                node = (node - 1) >> 1;
269	            }
270	            self.index[0] += 1;
271	        }
272	    }
273	
274	    /// Removes `lists[pos][sub_idx]`, merging or dropping sublists as needed.
275	    fn delete_at(&mut self, pos: usize, sub_idx: usize) -> T {
276	        let value = self.lists[pos].remove(sub_idx);
277	        self.len -= 1;
278	        let sub_len = self.lists[pos].len();
279	
280	        if sub_len > (self.load >> 1) || self.lists.len() == 1 {
281	            if sub_len == 0 {
282	                // Only possible with a single, now-empty sublist.
283	                self.lists.remove(pos);
284	                self.index.clear();
285	                self.offset = 0;
286	            } else if !self.index.is_empty() {
287	                let mut node = self.offset + pos;
288	                while node > 0 {
289	                    self.index[node] -= 1;
290	                    node = (node - 1) >> 1;
291	                }
292	                self.index[0] -= 1;
293	            }
294	        } else {
295	            // Sublist ran too thin: fold it into its left neighbour, then let
296	            // `expand` split the result back apart if it grew too large.
297	            let pos = if pos == 0 { 1 } else { pos };
298	            let prev = pos - 1;
299	            let moved = self.lists.remove(pos);
300	            self.lists[prev].extend(moved);
301	            self.index.clear();
302	            self.offset = 0;
303	            self.expand(prev);
304	        }
305	
306	        self.ensure_index();
307	        value
308	    }
309	
310	    /// Binary searches the sublist maxima; `go_right` reports "look further right".
311	    fn maxes_partition_point<F>(&self, mut go_right: F) -> usize
312	    where
313	        F: FnMut(&T) -> bool,
314	    {
315	        let mut lo = 0usize;
316	        let mut hi = self.lists.len();
317	        while lo < hi {
318	            let mid = lo + (hi - lo) / 2;
319	            let max = self.lists[mid]
320	                .last()
321	                .expect("sublists are never left empty");
322	            if go_right(max) {
323	                lo = mid + 1;
324	            } else {
325	                hi = mid;
326	            }
327	        }
328	        lo
329	    }
330	
331	    /// Finds the first element for which `cmp` is not `Less`, as `(sublist, offset)`.
332	    ///
333	    /// `cmp` compares a stored element against the sought key.
334	    fn seek_by<F>(&self, cmp: &mut F) -> (usize, usize)
335	    where
336	        F: FnMut(&T) -> Ordering,
337	    {
338	        if self.lists.is_empty() {
339	            return (0, 0);
340	        }
341	        let pos = self.maxes_partition_point(|max| cmp(max) == Ordering::Less);
342	        if pos == self.lists.len() {
343	            return (pos, 0);
344	        }
345	        let sub_idx = self.lists[pos].partition_point(|item| cmp(item) == Ordering::Less);
346	        (pos, sub_idx)
347	    }
348	
349	    /// Position of an element comparing `Equal` under `cmp`, if present.
350	    fn locate_by<F>(&self, mut cmp: F) -> Option<(usize, usize)>
351	    where
352	        F: FnMut(&T) -> Ordering,
353	    {
354	        let (pos, sub_idx) = self.seek_by(&mut cmp);
355	        let sub = self.lists.get(pos)?;
356	        match sub.get(sub_idx) {
357	            Some(item) if cmp(item) == Ordering::Equal => Some((pos, sub_idx)),
358	            _ => None,
359	        }
360	    }
361	
362	    /// Returns a reference to an element comparing `Equal` under `cmp`.
363	    pub fn find_by<F>(&self, cmp: F) -> Option<&T>
364	    where
365	        F: FnMut(&T) -> Ordering,
366	    {
367	        let (pos, sub_idx) = self.locate_by(cmp)?;
368	        Some(&self.lists[pos][sub_idx])
369	    }
370	
371	    /// Returns a mutable reference to an element comparing `Equal` under `cmp`.
372	    ///
373	    /// The caller must not mutate the element in a way that changes its order.
374	    pub fn find_mut_by<F>(&mut self, cmp: F) -> Option<&mut T>
375	    where
376	        F: FnMut(&T) -> Ordering,
377	    {
378	        let (pos, sub_idx) = self.locate_by(cmp)?;
379	        Some(&mut self.lists[pos][sub_idx])
380	    }
381	
382	    /// Removes and returns an element comparing `Equal` under `cmp`.
383	    pub fn remove_by<F>(&mut self, cmp: F) -> Option<T>
384	    where
385	        F: FnMut(&T) -> Ordering,
386	    {
387	        let (pos, sub_idx) = self.locate_by(cmp)?;
388	        Some(self.delete_at(pos, sub_idx))
389	    }
390	
391	    /// Rank of the first element comparing `Equal` or `Greater` under `cmp`.
392	    pub fn bisect_left_by<F>(&self, mut cmp: F) -> usize
393	    where
394	        F: FnMut(&T) -> Ordering,
395	    {
396	        let (pos, sub_idx) = self.seek_by(&mut cmp);
397	        if pos == self.lists.len() {
398	            self.len
399	        } else {
400	            self.rank_of(pos, sub_idx)
401	        }
402	    }
403	
404	    /// Rank of the first element comparing `Greater` under `cmp`.
405	    pub fn bisect_right_by<F>(&self, mut cmp: F) -> usize
406	    where
407	        F: FnMut(&T) -> Ordering,
408	    {
409	        // Treat `Equal` as "keep going right" to land past the run of equals.
410	        let mut shifted = |item: &T| match cmp(item) {
411	            Ordering::Greater => Ordering::Greater,
412	            _ => Ordering::Less,
413	        };
414	        let (pos, sub_idx) = self.seek_by(&mut shifted);
415	        if pos == self.lists.len() {
416	            self.len
417	        } else {
418	            self.rank_of(pos, sub_idx)
419	        }
420	    }
421	
422	    /// Replaces the sublists with `values`, which must already be sorted.
423	    pub(crate) fn rebuild_from_sorted(&mut self, values: Vec<T>) {
424	        self.clear();
425	        let load = self.load;
426	        let mut lists: Vec<Vec<T>> = Vec::with_capacity(values.len() / load + 1);
427	        let mut current: Vec<T> = Vec::with_capacity(load.min(values.len()));
428	        let mut len = 0usize;
429	        for value in values {
430	            current.push(value);
431	            len += 1;
432	            if current.len() == load {
433	                lists.push(std::mem::replace(&mut current, Vec::with_capacity(load)));
434	            }
435	        }
436	        if !current.is_empty() {
437	            lists.push(current);
438	        }
439	        self.lists = lists;
440	        self.len = len;
441	        self.build_index();
442	    }
443	}
444	
445	impl<T: Ord> SortedList<T> {
446	    /// Inserts `value`, keeping any existing equal elements.
447	    pub fn insert(&mut self, value: T) {
448	        if self.lists.is_empty() {
449	            self.lists.push(vec![value]);
450	            self.len = 1;
451	            self.build_index();
452	            return;
453	        }
454	        // `bisect_right` semantics: land after equal elements.
455	        let pos = self.maxes_partition_point(|max| *max <= value);
456	        if pos == self.lists.len() {
457	            let pos = self.lists.len() - 1;
458	            self.lists[pos].push(value);
459	            self.len += 1;
460	            self.expand(pos);
461	        } else {
462	            let sub_idx = self.lists[pos].partition_point(|item| *item <= value);
463	            self.lists[pos].insert(sub_idx, value);
464	            self.len += 1;
465	            self.expand(pos);
466	        }
467	        self.ensure_index();
468	    }
469	
470	    /// Inserts `value` only when no equal element is present.
471	    ///
472	    /// Returns `true` when the value was inserted.
473	    pub fn insert_if_absent(&mut self, value: T) -> bool {
474	        if self.lists.is_empty() {
475	            self.insert(value);
476	            return true;
477	        }
478	        let pos = self.maxes_partition_point(|max| *max < value);
479	        if pos == self.lists.len() {
480	            let pos = self.lists.len() - 1;
481	            self.lists[pos].push(value);
482	            self.len += 1;
483	            self.expand(pos);
484	        } else {
485	            let sub_idx = self.lists[pos].partition_point(|item| *item < value);
486	            if self.lists[pos]
487	                .get(sub_idx)
488	                .map_or(false, |item| *item == value)
489	            {
490	                return false;
491	            }
492	            self.lists[pos].insert(sub_idx, value);
493	            self.len += 1;
494	            self.expand(pos);
495	        }
496	        self.ensure_index();
497	        true
498	    }
499	
500	    /// Inserts `value`, replacing and returning an existing equal element.
501	    pub fn insert_or_replace(&mut self, value: T) -> Option<T> {
502	        if self.lists.is_empty() {
503	            self.insert(value);
504	            return None;
505	        }
506	        let pos = self.maxes_partition_point(|max| *max < value);
507	        if pos == self.lists.len() {
508	            let pos = self.lists.len() - 1;
509	            self.lists[pos].push(value);
510	            self.len += 1;
511	            self.expand(pos);
512	        } else {
513	            let sub_idx = self.lists[pos].partition_point(|item| *item < value);
514	            if self.lists[pos]
515	                .get(sub_idx)
516	                .map_or(false, |item| *item == value)
517	            {
518	                return Some(std::mem::replace(&mut self.lists[pos][sub_idx], value));
519	            }
520	            self.lists[pos].insert(sub_idx, value);
521	            self.len += 1;
522	            self.expand(pos);
523	        }
524	        self.ensure_index();
525	        None
526	    }
527	
528	    /// Returns `true` when an element equal to `value` is present.
529	    pub fn contains(&self, value: &T) -> bool {
530	        self.locate_by(|item| item.cmp(value)).is_some()
531	    }
532	
533	    /// Removes one element equal to `value`, reporting whether it was found.
534	    pub fn remove(&mut self, value: &T) -> bool {
535	        self.remove_by(|item| item.cmp(value)).is_some()
536	    }
537	
538	    /// Rank of the first element not less than `value`.
539	    pub fn bisect_left(&self, value: &T) -> usize {
540	        self.bisect_left_by(|item| item.cmp(value))
541	    }
542	
543	    /// Rank of the first element greater than `value`.
544	    pub fn bisect_right(&self, value: &T) -> usize {
545	        self.bisect_right_by(|item| item.cmp(value))
546	    }
547	
548	    /// Rank of the first element equal to `value`, if present.
549	    pub fn index_of(&self, value: &T) -> Option<usize> {
550	        let (pos, sub_idx) = self.locate_by(|item| item.cmp(value))?;
551	        Some(self.rank_of(pos, sub_idx))
552	    }
553	
554	    /// Number of elements equal to `value`.
555	    pub fn count(&self, value: &T) -> usize {
556	        self.bisect_right(value) - self.bisect_left(value)
557	    }
558	
559	    /// Inserts every item, choosing between bulk rebuild and repeated inserts.
560	    pub fn extend_from<I: IntoIterator<Item = T>>(&mut self, items: I) {
561	        let mut values: Vec<T> = items.into_iter().collect();
562	        if values.is_empty() {
563	            return;
564	        }
565	        values.sort();
566	        if !self.lists.is_empty() {
567	            if values.len() * 4 < self.len {
568	                // Small addition relative to the list: point inserts win.
569	                for value in values {
570	                    self.insert(value);
571	                }
572	                return;
573	            }
574	            let existing = std::mem::take(&mut self.lists);
575	            let mut merged = Vec::with_capacity(self.len + values.len());
576	            for sub in existing {
577	                merged.extend(sub);
578	            }
579	            merged.extend(values);
580	            merged.sort();
581	            values = merged;
582	        }
583	        self.rebuild_from_sorted(values);
584	    }
585	}
