593	impl<'a, T> Iterator for Iter<'a, T> {
594	    type Item = &'a T;
595	
596	    fn next(&mut self) -> Option<Self::Item> {
597	        let item = self.inner.next();
598	        if item.is_some() {
599	            self.remaining -= 1;
600	        }
601	        item
602	    }
603	
604	    fn size_hint(&self) -> (usize, Option<usize>) {
605	        (self.remaining, Some(self.remaining))
606	    }
607	}
