697	    /// Checks every structural invariant against a straightforward model.
698	    fn assert_consistent<T: Ord + Clone + fmt::Debug>(list: &SortedList<T>, model: &[T]) {
699	        assert_eq!(list.len(), model.len(), "len mismatch");
700	        assert_eq!(list.to_vec(), model.to_vec(), "contents mismatch");
701	
702	        for sub in &list.lists {
703	            assert!(!sub.is_empty(), "sublist must never be empty");
704	            assert!(
705	                sub.len() <= list.load * 2,
706	                "sublist exceeded 2 * load: {}",
707	                sub.len()
708	            );
709	        }
710	
711	        // Positional access must agree with the model at every rank.
712	        for (rank, expected) in model.iter().enumerate() {
713	            assert_eq!(list.get(rank), Some(expected), "get({rank})");
714	        }
715	        assert_eq!(list.get(model.len()), None, "get past the end");
716	
717	        // The index tree, when present, must describe the real sublist sizes.
718	        if !list.index.is_empty() {
719	            assert_eq!(list.index[0], list.len, "index root must equal len");
720	            for (pos, sub) in list.lists.iter().enumerate() {
721	                assert_eq!(
722	                    list.index[list.offset + pos],
723	                    sub.len(),
724	                    "leaf {pos} out of date"
725	                );
726	            }
727	        }
728	    }
