1	//! A sorted set of unique values, layered on [`SortedList`].
2	//!
3	//! Membership tests and insertions are binary searches over the same two-level
4	//! layout the list uses, so no hashing -- and therefore no `Hash` bound -- is
5	//! required: `Ord` alone is enough.
6	
7	use std::cmp::Ordering;
8	use std::fmt;
9	
10	// Relative paths keep this module usable both as a library crate root's child
11	// and as an inlined module of a standalone `rustc` build.
12	use super::sorted_list::{Iter, SortedList, DEFAULT_LOAD_FACTOR};
13	
14	/// A sorted collection holding at most one copy of each value.
15	pub struct SortedSet<T> {
16	    list: SortedList<T>,
17	}
18	
19	impl<T> SortedSet<T> {
20	    /// Creates an empty set using [`DEFAULT_LOAD_FACTOR`].
21	    pub fn new() -> Self {
22	        Self::with_load_factor(DEFAULT_LOAD_FACTOR)
23	    }
24	
25	    /// Creates an empty set with an explicit load factor.
26	    pub fn with_load_factor(load: usize) -> Self {
27	        SortedSet {
28	            list: SortedList::with_load_factor(load),
29	        }
30	    }
31	
32	    /// Number of values in the set.
33	    pub fn len(&self) -> usize {
34	        self.list.len()
35	    }
36	
37	    /// Returns `true` when the set holds no values.
38	    pub fn is_empty(&self) -> bool {
39	        self.list.is_empty()
40	    }
41	
42	    /// The configured load factor.
43	    pub fn load_factor(&self) -> usize {
44	        self.list.load_factor()
45	    }
46	
47	    /// Removes every value.
48	    pub fn clear(&mut self) {
49	        self.list.clear();
50	    }
51	
52	    /// Iterates over the values in ascending order.
53	    pub fn iter(&self) -> Iter<'_, T> {
54	        self.list.iter()
55	    }
56	
57	    /// Returns the value at rank `idx`.
58	    pub fn get(&self, idx: usize) -> Option<&T> {
59	        self.list.get(idx)
