156	    /// Values present in `self` or `other`.
157	    pub fn union_with(&self, other: &SortedSet<T>) -> SortedSet<T>
158	    where
159	        T: Clone,
160	    {
161	        let mut merged = Vec::with_capacity(self.len() + other.len());
162	        self.merge_walk(other, |ordering| ordering != Ordering::Greater, true, &mut merged);
163	        SortedSet::from_sorted_unique(merged, self.load_factor())
164	    }
