#[path = "src/lib.rs"]
mod sc;
use sc::{SortedList, SortedSet, SortedDict};

fn lcg(s: &mut u64) -> u64 {
    *s = s.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
    *s >> 33
}

fn main() {
    // 1) SortedList vs Vec model, heavy remove/pop to force merges + index rebuilds.
    for load in [1usize, 2, 3, 4, 5, 7, 8, 13, 16, 31, 32, 64] {
        let mut st = 0x9E3779B97F4A7C15u64 ^ (load as u64 * 0x1234567);
        let mut list = SortedList::with_load_factor(load);
        let mut model: Vec<i64> = Vec::new();
        for step in 0..20000u32 {
            let v = (lcg(&mut st) % 400) as i64;
            match lcg(&mut st) % 10 {
                0..=4 => { list.insert(v); let at = model.partition_point(|x| *x <= v); model.insert(at, v); }
                5 => { let p = model.contains(&v); assert_eq!(list.remove(&v), p, "L{load} s{step}");
                       if p { let at = model.iter().position(|x| *x==v).unwrap(); model.remove(at); } }
                6 => { if !model.is_empty() { let r = (lcg(&mut st) as usize) % model.len();
                       assert_eq!(list.pop(r), Some(model.remove(r)), "L{load} s{step}"); } }
                7 => { assert_eq!(list.pop_first(), if model.is_empty(){None}else{Some(model.remove(0))}); }
                8 => { assert_eq!(list.pop_last(), if model.is_empty(){None}else{Some(model.remove(model.len()-1))}); }
                _ => { // random-rank/bisect/iterator reads
                       let r = (lcg(&mut st) as usize) % (model.len()+1);
                       assert_eq!(list.get(r), model.get(r), "L{load} s{step} get({r})");
                       assert_eq!(list.bisect_left(&v), model.partition_point(|x| *x<v));
                       assert_eq!(list.bisect_right(&v), model.partition_point(|x| *x<=v));
                       assert_eq!(list.index_of(&v), if model.contains(&v){Some(model.partition_point(|x| *x<v))}else{None});
                       assert_eq!(list.count(&v), model.iter().filter(|x| **x==v).count());
                       assert_eq!(list.iter().count(), model.len());
                       assert_eq!(list.iter().rev().count(), model.len());
                       assert_eq!(list.len(), model.len());
                       if lcg(&mut st)%50==0 { assert_eq!(list.to_vec(), model); } }
            }
        }
        assert_eq!(list.to_vec(), model, "final L{load}");
    }
    // 2) SortedSet algebra vs BTreeSet across many sizes/load factors.
    for load in [1usize, 2, 3, 5, 1000] {
        let mut st = 0xDEADBEEFCAFEu64 ^ (load as u64);
        for _ in 0..40 {
            let na = (lcg(&mut st) % 3000) as usize;
            let nb = (lcg(&mut st) % 3000) as usize;
            let mut a = SortedSet::with_load_factor(load);
            let mut b = SortedSet::with_load_factor(load);
            let mut ma = std::collections::BTreeSet::new();
            let mut mb = std::collections::BTreeSet::new();
            for _ in 0..na { let v = (lcg(&mut st) % 5000) as i64; a.insert(v); ma.insert(v); }
            for _ in 0..nb { let v = (lcg(&mut st) % 5000) as i64; b.insert(v); mb.insert(v); }
            assert_eq!(a.len(), ma.len()); assert_eq!(b.len(), mb.len());
            assert_eq!(a.union_with(&b).to_vec(), ma.union(&mb).cloned().collect::<Vec<i64>>());
            assert_eq!(a.intersection_with(&b).to_vec(), ma.intersection(&mb).cloned().collect::<Vec<i64>>());
            assert_eq!(a.difference_with(&b).to_vec(), ma.difference(&mb).cloned().collect::<Vec<i64>>());
            assert_eq!(a.symmetric_difference_with(&b).to_vec(), ma.symmetric_difference(&mb).cloned().collect::<Vec<i64>>());
            assert_eq!(a.is_subset_of(&b), ma.is_subset(&mb));
            assert_eq!(a.is_disjoint_from(&b), ma.is_disjoint(&mb));
            let u = a.union_with(&b);
            for v in 0..60i64 { assert_eq!(u.contains(&v), ma.contains(&v)||mb.contains(&v)); }
            for r in 0..u.len() { assert!(u.get(r).is_some()); }
        }
    }
    // 3) SortedDict vs BTreeMap
    for load in [1usize, 2, 4, 1000] {
        let mut st = 0xABCDEF12345u64 ^ (load as u64);
        let mut d = SortedDict::with_load_factor(load);
        let mut m = std::collections::BTreeMap::new();
        for _ in 0..8000 {
            let k = (lcg(&mut st) % 500) as i64;
            match lcg(&mut st) % 4 {
                0 => { assert_eq!(d.remove(&k), m.remove(&k)); }
                1 => { assert_eq!(d.get(&k), m.get(&k)); assert_eq!(d.contains_key(&k), m.contains_key(&k)); }
                2 => { assert_eq!(d.pop_first(), m.keys().next().cloned().map(|kk| (kk, m.remove(&kk).unwrap()))); }
                _ => { let v = (lcg(&mut st)%1000) as i64; assert_eq!(d.insert(k,v), m.insert(k,v)); }
            }
            assert_eq!(d.len(), m.len());
        }
        assert_eq!(d.keys().cloned().collect::<Vec<i64>>(), m.keys().cloned().collect::<Vec<i64>>());
    }
    // 4) Huge single-sublist growth then full drain (exercises many splits then all merges).
    let mut l: SortedList<i32> = SortedList::with_load_factor(1000);
    for v in 0..30000 { l.insert(v); }
    while l.pop_first().is_some() {}
    assert!(l.is_empty());
    let mut l: SortedList<i32> = SortedList::with_load_factor(1000);
    for v in (0..30000).rev() { l.insert(v); }
    while l.pop_last().is_some() {}
    assert!(l.is_empty());
    // 5) Interleaved middle drain (worst case for merges).
    let mut l: SortedList<i32> = SortedList::with_load_factor(3);
    for v in 0..5000 { l.insert(v); }
    while !l.is_empty() { let r = l.len()/2; l.pop(r).unwrap(); }
    println!("STRESS OK");
}
